import sailpoint.object.ManagedAttribute;
import java.util.List;
import java.util.ArrayList;
import java.util.Set;
import java.util.HashSet;
import java.util.Collections;

String SOURCE_ID = "6659e1f4005c400e8ce339362afef7c6";
String DEFAULT_VALUE = "-";

String identityAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "identityAttribute");
String entitlementAccAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementAccountAttribute");
String entitlementParentAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementParentAttribute");
String entitlementDisplayAttr = idn.getSourceAttributeBySourceId(SOURCE_ID, "entitlementDisplayAttribute");
String hierarchySep = idn.getSourceAttributeBySourceId(SOURCE_ID, "hierarchySeparator");

if (identityAttr == null || entitlementAccAttr == null || entitlementDisplayAttr == null) {
    return DEFAULT_VALUE;
}

String entitlementValue = null;
if (identity != null) {
    Object val = identity.getAttribute(identityAttr);
    if (val != null) {
        entitlementValue = val.toString();
    }
}

if (entitlementValue == null || entitlementValue.trim().isEmpty()) {
    return DEFAULT_VALUE;
}

List path = new ArrayList();
Set visited = new HashSet();
String current = entitlementValue;
int maxDepth = 20;

while (current != null && !current.trim().isEmpty() && !visited.contains(current) && path.size() < maxDepth) {
    visited.add(current);

    sailpoint.rule.ManagedAttributeDetails details = idn.getManagedAttributeDetails(
        SOURCE_ID, entitlementAccAttr, current, ManagedAttribute.Type.Entitlement
    );
    if (details == null) {
        break;
    }

    java.util.Map attrs = details.getAttributes();
    if (attrs == null) {
        break;
    }

    Object displayValue = attrs.get(entitlementDisplayAttr);
    if (displayValue != null) {
        path.add(displayValue.toString());
    }

    Object parentVal = attrs.get(entitlementParentAttr);
    current = (parentVal != null) ? parentVal.toString() : null;
}

if (path.isEmpty()) {
    return DEFAULT_VALUE;
}

Collections.reverse(path);
StringBuilder result = new StringBuilder();
for (int i = 0; i < path.size(); i++) {
    if (i > 0 && hierarchySep != null) {
        result.append(hierarchySep);
    }
    result.append(path.get(i));
}
return result.toString();
